arguments.command:
curl -s https://api.linear.app/graphql -H "Authorization: <TOKEN>" -H "Content-Type: application/json" -d '{"query":"{ __schema { mutationType { fields { name args { name type { kind name ofType { kind name ofType { kind name } } } } } } } }" }' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__schema']['mutationType']['fields']:
    if f['name'] in ('issueUpdate','issueCreate'):
        print(f['name'])
        for a in f['args']:
            t=a['type']
            print('  ',a['name'], t['name'] or t['ofType']['name'] if t.get('ofType') else t['kind'])
"

